* { box-sizing: border-box; }
:root {
  color-scheme: dark;
  font-family: system-ui, sans-serif;
  font-size: 16px;
  color: #f5f0dc;
  background: #182b35;
}
body {
  min-width: 360px;
  min-height: 100vh;
  margin: 0;
  display: grid;
  place-items: center;
  padding: 24px 16px;
  background-color: #182b35;
  background-image: radial-gradient(#38515a 1.5px, transparent 1.5px);
  background-size: 24px 24px;
}
button { font: inherit; }
.board {
  width: min(100%, 620px);
  padding: clamp(24px, 6vw, 48px);
  border: 4px solid #101f27;
  border-radius: 8px;
  background: #24414a;
  box-shadow: 8px 8px 0 #101f27;
}
.header { text-align: center; }
.eyebrow, .result-label {
  margin: 0;
  color: #f0c75e;
  font-size: .8rem;
  font-weight: 800;
  letter-spacing: .13em;
}
h1 { margin: 10px 0 8px; font-size: clamp(2rem, 8vw, 3rem); line-height: 1.1; }
.intro { margin: 0; color: #d0ddd8; }
.game { margin-top: 32px; padding: 20px; border: 2px solid #45636a; border-radius: 6px; background: #1c343d; }
.status-row { display: flex; justify-content: space-between; align-items: center; gap: 12px; color: #d0ddd8; }
.status-row p { margin: 0; }
.roll-count { white-space: nowrap; }
.roll-count span { color: #f0c75e; font-weight: 800; }
.dice-row { display: flex; flex-wrap: wrap; justify-content: center; gap: 12px; margin: 24px 0 12px; }
.die {
  display: grid;
  place-items: center;
  width: clamp(48px, 12vw, 72px);
  aspect-ratio: 1;
  padding: 0;
  border: 3px solid #101f27;
  border-radius: 8px;
  color: #182b35;
  background: #f5f0dc;
  box-shadow: 3px 3px 0 #101f27;
  cursor: pointer;
  font-size: clamp(2rem, 8vw, 3rem);
  line-height: 1;
  transition: transform .12s ease, background-color .12s ease, box-shadow .12s ease;
}
.die:hover { transform: translateY(-3px); }
.die:active { transform: translateY(2px); box-shadow: 1px 1px 0 #101f27; }
.die:focus-visible, .button:focus-visible { outline: 3px solid #f0c75e; outline-offset: 4px; }
.die[aria-pressed="true"] { color: #182b35; background: #f0c75e; transform: translateY(-4px); box-shadow: 3px 6px 0 #101f27; }
.hint { margin: 0; text-align: center; color: #aebfba; font-size: .9rem; }
.actions { display: flex; flex-wrap: wrap; justify-content: center; gap: 12px; margin-top: 24px; }
.button { min-height: 48px; padding: 10px 20px; border: 2px solid #101f27; border-radius: 5px; font-weight: 800; cursor: pointer; transition: transform .12s ease, filter .12s ease; }
.button:hover { filter: brightness(1.1); transform: translateY(-2px); }
.button:active { transform: translateY(2px); }
.button:disabled { cursor: not-allowed; opacity: .55; transform: none; }
.button-primary { color: #182b35; background: #f0c75e; box-shadow: 3px 3px 0 #101f27; }
.button-secondary { color: #f5f0dc; background: #38515a; box-shadow: 3px 3px 0 #101f27; }
.result { margin-top: 24px; padding: 16px; border: 2px dashed #45636a; text-align: center; }
.result-label { font-size: .72rem; }
#hand-name { margin: 5px 0 0; color: #f0c75e; font-size: 1.35rem; font-weight: 800; }
footer { margin-top: 22px; color: #aebfba; text-align: center; font-size: .85rem; }
@media (max-width: 420px) {
  .game { padding: 16px 12px; }
  .dice-row { gap: 9px; }
  .actions { flex-direction: column; }
  .button { width: 100%; }
}

const diceContainer = document.querySelector('#dice');
const rerollsDisplay = document.querySelector('#rerolls');
const statusDisplay = document.querySelector('#round-status');
const handDisplay = document.querySelector('#hand-name');
const rollButton = document.querySelector('#roll-button');
const newButton = document.querySelector('#new-button');

let dice = [];
let rerolls = 2;
let started = false;
let finished = false;

const faceSymbols = ['', '⚀', '⚁', '⚂', '⚃', '⚄', '⚅'];

function handName(values) {
  const counts = [...values.reduce((map, value) => map.set(value, (map.get(value) || 0) + 1), new Map()).values()].sort((a, b) => b - a);
  const unique = [...new Set(values)].sort((a, b) => a - b);
  const straight = unique.length === 5 && (unique[4] - unique[0] === 4 || unique.join(',') === '1,2,3,4,6');

  if (counts[0] === 5) return 'Five of a kind';
  if (counts[0] === 4) return 'Four of a kind';
  if (counts[0] === 3 && counts[1] === 2) return 'Full house';
  if (straight) return 'Straight';
  if (counts[0] === 3) return 'Three of a kind';
  if (counts[0] === 2 && counts[1] === 2) return 'Two pair';
  if (counts[0] === 2) return 'Pair';
  return 'High dice';
}

function render() {
  diceContainer.replaceChildren(...dice.map((die, index) => {
    const button = document.createElement('button');
    button.type = 'button';
    button.className = 'die';
    button.textContent = faceSymbols[die.value];
    button.setAttribute('aria-label', `Die ${index + 1}: ${die.value}${die.held ? ', held' : ', not held'}`);
    button.setAttribute('aria-pressed', String(die.held));
    button.addEventListener('click', () => {
      if (finished) return;
      die.held = !die.held;
      render();
      diceContainer.children[index].focus();
    });
    return button;
  }));
  rerollsDisplay.textContent = String(rerolls);
  rollButton.disabled = finished;
}

function roll() {
  if (finished) return;
  if (started && rerolls === 0) return;

  dice = dice.map(die => die.held ? die : { value: Math.floor(Math.random() * 6) + 1, held: false });
  if (!started) {
    started = true;
    statusDisplay.textContent = 'Choose dice to hold';
  } else {
    rerolls -= 1;
    statusDisplay.textContent = rerolls ? 'Choose dice to hold' : 'Final roll complete';
  }
  render();
  handDisplay.textContent = handName(dice.map(die => die.value));

  if (rerolls === 0) {
    finished = true;
    statusDisplay.textContent = 'Round complete';
    render();
  }
}

function newRound() {
  dice = Array.from({ length: 5 }, () => ({ value: 1, held: false }));
  rerolls = 2;
  started = false;
  finished = false;
  statusDisplay.textContent = 'Your opening roll';
  handDisplay.textContent = 'Roll to see your hand';
  render();
}

rollButton.addEventListener('click', roll);
newButton.addEventListener('click', newRound);
newRound();
